    "show_all_faqs": "Show all questions",
    "faq_1_q": "How do I book a procurement slot?",
    "faq_1_a": "Open Find a Procurement Center, select a center, choose an available date and slot, review the booking details, and confirm your booking.",
    "faq_2_q": "How do I know whether my booking is confirmed?",
    "faq_2_a": "After successful booking, KisanSetu displays your booking confirmation along with your digital token and scheduled arrival slot.",
    "faq_3_q": "How can I check my queue position?",
    "faq_3_a": "Open Live Queue from your dashboard to see your current position, tokens ahead, and estimated waiting time in real time.",
    "faq_4_q": "Why did my estimated waiting time change?",
    "faq_4_a": "Queue estimates adjust dynamically based on actual weighing speeds, moisture inspection rates, and vehicle clearances at the Mandi.",
    "faq_5_q": "What does 'Delayed' mean?",
    "faq_5_a": "Delayed means procurement operations are taking longer than normal due to weather, high inflow, or technical inspections at the weighbridge.",
    "faq_6_q": "What happens if there are no available slots?",
    "faq_6_a": "The system shows the centre is at daily capacity and suggests the next earliest open date or nearby Mandi centres with open slots.",
    "faq_7_q": "Can I reschedule or cancel my booking?",
    "faq_7_a": "Yes, you can reschedule from My Bookings up to 2 hours before your arrival window, subject to slot availability.",
    "faq_8_q": "What should I do if my internet connection is lost?",
    "faq_8_a": "Your token number and booking SMS work offline at the gate. The gate staff can verify your booking with your mobile number.",
    "faq_9_q": "How do I change my language?",
    "faq_9_a": "Click the Language Support selector in the header or at the bottom footer. Choose from English, हिंदी, मराठी, বাংলা, ਪੰਜਾਬੀ, or اردو.",
    "faq_10_q": "What happens if the procurement center is delayed?",
    "faq_10_a": "The live tracker shows updated arrival recommendations so you don't have to wait under the sun at the Mandi.",
    "privacy_hero_title": "Privacy Notice",
    "privacy_hero_sub": "KisanSetu is designed with privacy in mind. This page explains, in simple language, how information is handled within the product.",
    "privacy_prototype_banner": "Project Privacy Notice: KisanSetu is an agricultural queue coordination prototype designed for Smart India Hackathon 2026. Data displayed is for demonstrative, testing, and operational simulation purposes.",
    "privacy_sections_title": "Document Sections",
    "privacy_sec_1_title": "Information We May Use",
    "privacy_sec_1_desc": "Only essential information needed for booking verification, SMS alerts, and queue coordination is gathered: farmer name, mobile number, commodity, and vehicle type.",
    "privacy_sec_2_title": "How Information Is Used",
    "privacy_sec_2_desc": "Information is used strictly to reserve procurement slots, calculate queue wait times, send SMS updates, and facilitate weighing receipts at the Mandi.",
    "privacy_sec_3_title": "Location Information",
    "privacy_sec_3_desc": "Location access is used only to show your distance to the nearest procurement centres. Your exact live location is never tracked or shared.",
    "privacy_sec_4_title": "Protecting Information",
    "privacy_sec_4_desc": "All communication is encrypted via modern HTTPS/TLS protocols. Access is restricted to authorized Mandi procurement staff.",
    "privacy_sec_5_title": "Who Can Access Information",
    "privacy_sec_5_desc": "Only designated Mandi operators and authorized procurement agencies see your booking details for the purpose of weighing and MSP settlement.",
    "privacy_sec_6_title": "Data Retention",
    "privacy_sec_6_desc": "Operational records are stored for the duration of the procurement season to ensure transparent audit trails for farmers.",
    "terms_hero_title": "Terms of Use",
    "terms_hero_sub": "These terms describe the intended use of KisanSetu. Final production terms should be reviewed and approved by the operating organization.",
    "terms_sec_1": "1.0 Using KisanSetu",
    "terms_sec_1_desc": "KisanSetu is provided to assist farmers in booking arrival slots and tracking queues. All users must provide genuine contact details.",
    "terms_sec_2": "2.0 Bookings and Slots",
    "terms_sec_2_desc": "A booked slot represents an arrival time window at the centre. It helps regulate traffic but is subject to operational conditions at the weighbridge.",
    "terms_sec_3": "3.0 Queue and Waiting-Time",
    "terms_sec_3_desc": "Wait-time estimations are calculated dynamically. Factors such as weather, moisture checks, and emergency vehicle priority may affect timings.",
    "terms_sec_4": "4.0 Procurement Information",
    "terms_sec_4_desc": "Weights, quality inspections, and MSP calculations displayed on the platform are recorded by authorized Mandi operators.",
    "terms_sec_5": "5.0 User Responsibilities",
    "terms_sec_5_desc": "Farmers must arrive with their digital token or SMS pass, clean produce meeting Fair Average Quality (FAQ) standards, and valid registration.",
    "terms_sec_6": "6.0 Platform Availability",
    "terms_sec_6_desc": "While we strive for 99.9% uptime during procurement seasons, offline SMS confirmation remains valid in case of network outages.",
    "terms_sec_7": "7.0 Prohibited Use",
    "terms_sec_7_desc": "Users may not create automated fake bookings, manipulate token positions, or misuse support channels.",
    "terms_sec_8": "8.0 Changes to Terms",
    "terms_sec_8_desc": "Operating policies and procurement rules may be updated in accordance with State Agricultural Marketing Board guidelines.",
