    "faq_7_q": "আমি কি আমার বুকিং পুনর্নির্ধারণ বা বাতিল করতে পারি?",
    "faq_7_a": "হ্যাঁ, আপনি স্লট খালি থাকা সাপেক্ষে আগমনের ২ ঘণ্টা আগে পর্যন্ত 'আমার বুকিং' থেকে পরিবর্তন করতে পারেন।",
    "faq_8_q": "ইন্টারনেট সংযোগ বিচ্ছিন্ন হলে আমার কী করা উচিত?",
    "faq_8_a": "আপনার টোকেন নম্বর এবং এসএমএস গেটে অফলাইনেও কাজ করে। গেট কর্মীরা আপনার মোবাইল নম্বর দিয়ে যাচাই করতে পারেন।",
    "faq_9_q": "আমি কীভাবে ভাষা পরিবর্তন করব?",
    "faq_9_a": "হেডার বা ফুটারের 'ভাষা সহায়তা' বাটনে ক্লিক করুন। English, हिंदी, मराठी, বাংলা, ਪੰਜਾਬੀ বা اردو বেছে নিন।",
    "faq_10_q": "সংগ্রহ কেন্দ্রে দেরি হলে কী হবে?",
    "faq_10_a": "লাইভ ট্র্যাকার নতুন আগমনের সময় দেখায় যাতে আপনাকে মান্ডিতে রোদে অপেক্ষা করতে না হয়।",
