    "faq_1_q": "خریداری کا سلاٹ کیسے بک کریں؟",
    "faq_1_a": "خریداری مرکز تلاش کریں کھولیں، مرکز منتخب کریں، دستیاب تاریخ اور سلاٹ چنیں، اور تصدیق کریں۔",
    "faq_2_q": "مجھے کیسے معلوم ہوگا کہ میری بکنگ کی تصدیق ہو گئی ہے؟",
    "faq_2_a": "کامیاب بکنگ کے بعد، کسان سیتو آپ کے ڈیجیٹل ٹوکن اور وقت کے ساتھ تصدیق ظاہر کرتا ہے۔",
    "faq_3_q": "میں قطار میں اپنی پوزیشن کیسے دیکھ سکتا ہوں؟",
    "faq_3_a": "اپنے ڈیش بورڈ سے لائیو قطار کھولیں اور اپنی موجودہ پوزیشن، آگے موجود ٹوکنز اور تخمینی وقت لائیو دیکھیں۔",
    "faq_4_q": "میرا تخمینی انتظار کا وقت کیوں تبدیل ہوا؟",
    "faq_4_a": "منڈی میں وزن کی رفتار، نمی کی جانچ اور گاڑیوں کی روانگی کے مطابق قطار کا تخمینہ خودکار طور پر تبدیل ہوتا ہے۔",
    "faq_5_q": "'تاخیر' (Delayed) کا کیا مطلب ہے؟",
    "faq_5_a": "تاخیر کا مطلب ہے کہ موسم، زیادہ آمد یا وی برج پر تکنیکی جانچ کی وجہ سے عمل میں معمول سے زیادہ وقت لگ رہا ہے۔",
    "faq_6_q": "اگر کوئی سلاٹ دستیاب نہ ہو تو کیا ہوگا؟",
    "faq_6_a": "سسٹم ظاہر کرتا ہے کہ مرکز کی روزانہ کی گنجائش مکمل ہے اور اگلی دستیاب تاریخ یا قریبی مراکز تجویز کرتا ہے۔",
    "faq_7_q": "کیا میں اپنی بکنگ کا وقت تبدیل یا منسوخ کر سکتا ہوں؟",
    "faq_7_a": "جی ہاں، آپ سلاٹ کی دستیابی کے مطابق آمد کے وقت سے 2 گھنٹے پہلے تک 'میری بکنگز' سے وقت تبدیل کر سکتے ہیں۔",
    "faq_8_q": "اگر انٹرنیٹ کنکشن منقطع ہو جائے تو مجھے کیا کرنا چاہیے؟",
    "faq_8_a": "آپ کا ٹوکن نمبر اور ایس ایم ایس گیٹ پر آف لائن بھی کام کرتے ہیں۔ عملہ آپ کے موبائل نمبر سے تصدیق کر سکتا ہے۔",
    "faq_9_q": "میں اپنی زبان کیسے تبدیل کروں؟",
    "faq_9_a": "ہیڈر یا نیچے فوٹر میں 'زبان کی مدد' پر کلک کریں۔ انگریزی، ہندی، مراٹھی، بنگالی، پنجابی یا اردو میں سے انتخاب کریں۔",
    "faq_10_q": "اگر خریداری مرکز میں تاخیر ہو جائے تو کیا ہوگا؟",
    "faq_10_a": "لائیو ٹریکر نیا وقت ظاہر کرتا ہے تاکہ آپ کو دھوپ میں انتظار نہ کرنا پڑے۔",
